------------ import ------------
local cs_coroutine = require('XLua.cs_coroutine')
local Yielders = CS.Engine.Lib.Yielders
------------ import ------------

------------ define ------------
local KTool = CS.Engine.Lib.KTool
local Utils = CS.Engine.Tools.Utils
local Animator = CS.UnityEngine.Animator
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local RobotPet = CS.Game.Native.Common.RobotPet

local time = os.time
local KCookie = CS.Engine.Lib.KCookie

local IDLE_CHANGE_TIME = 30
local CHARGE_TIME = 69

------------ define ------------

local STATES = {
    CHARGE = 'charge', ---充电的状态
    IDLE = 'idle',
    IDLE1 = 'idleR1',
    IDLE2 = 'idleR2',
    CLICK = 'select',
    NEWS = 'news', ---新的消息小红点
    MOVE = 'move', ---移动方向
    DIRECTION = 'direction', ---移动方向
}

local IDLES = {STATES.IDLE1, STATES.IDLE2}

local Events = Events

---@class IRobotCat
local IRobotCat = Class('IRobotCat')

function IRobotCat:__init()
    self.animator = nil
    self.startTime = time()
    self.noTouchTime = time()
    self._behaviourAction = nil
    self.isUpdating = true
    self.curState = nil
    self._UIMainHomeSceneFocusShowEvent= nil
    self.moveHandle = nil
    self._redPointGo = nil
    self._telephoneGo = nil
    self._msgGo = nil
end

function IRobotCat:__delete()
    self.isUpdating = false
    self.animator = nil
    self.startTime = nil
    self.noTouchTime = nil
    self.curState = nil
    self._UIMainHomeSceneFocusShowEvent= nil
    self._redPointGo = nil
    self._telephoneGo = nil
    self._msgGo = nil
end

function IRobotCat:Awake()
    self._UIMainHomeSceneFocusShowEvent = Events.AddListener(Constants.EventNames.UIMainHomeSceneFocusShowEventName, Bind(self, self.OnUIMainHomeSceneFocusShowEventName))
    self._AllMainUIEvent = Events.AddListener('AllMainUI', Bind(self, self.OnAllMainUI))

    self.animator = KTool.GetComponent(self.controller.gameObject, typeof(Animator))
    self._behaviourAction = KTool.GetComponent(self.controller.gameObject, typeof(BehaviourAction))

    self._redPointGo = self.controller.gameObject.transform:Find("UI_10801_gantanhao")
    self._telephoneGo = self.controller.gameObject.transform:Find("UI_10801_dadianhua")
    self._msgGo = self.controller.gameObject.transform:Find("UI_10801_shengluehao")

    --机器人打开手机页面
    local quickTap = KTool.GetOrAddComponent(self.controller.gameObject, typeof(CS.HedgehogTeam.EasyTouch.QuickTap))
    if not isNull(quickTap) then
        quickTap.onTap:AddListener(Bind(self, self.OnExecuteOpenPhone))
    end

    self.moveHandle = Events.AddListener(Constants.EventNames.ROBOT_HOME_CATE_MOVE, function(param)
        self:Move(param)
    end)

    self.__EventHideOrShowWhiteCat = Events.AddListener("EventHideOrShowWhiteCat", function(active)
        KTool.SetActive(self.controller.gameObject, active)
    end)
end

function IRobotCat:Start()
    ---@type Engine.Lib.BehaviourAction
    local  behaviourAction = self._behaviourAction
    behaviourAction.UpdateAction = function()
        self:OnUpdate()
    end

    GameUtils.BindRedPoint(Constants.RedPointConst.Phone, self.controller.gameObject, true, nil, function(node)
        local isTrue = node.pointNum > 0
        self:ChangeCondition(STATES.NEWS, isTrue)
        --有小红点屏蔽掉动作更新
        if isTrue then
            self.isUpdating = false
        else
            self.isUpdating = true
        end

        local state = PhoneUtils.GetRedPointState()
        KTool.SetActive(self._telephoneGo, state == Constants.STATE.TELEPHONE)
        KTool.SetActive(self._msgGo, state == Constants.STATE.MESSAGE)
        KTool.SetActive(self._redPointGo, isTrue and state ~= Constants.STATE.TELEPHONE and state ~= Constants.STATE.MESSAGE)
    end)
end

--点击机器人打开手机页面
function IRobotCat:OnExecuteOpenPhone()
    --移动中点击直接返回
    if self.animator:GetBool(STATES.MOVE) then
        return
    end
    if checkNumber(KCookie.Get(Constants.IsOpnePageing)) == 1 then
        return
    end
    KCookie.Set(Constants.IsOpnePageing, 1)

    local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
    blocker:AddCondition("ExecuteOpenPhone")
    local isNewsState = self.animator:GetBool(STATES.NEWS)
    if isNewsState then
        self:ChangeCondition(STATES.NEWS, false)
    end
    ---播放一个离开动画
    --self.animator:SetTrigger(STATES.CLICK)
    self.animator:Play(STATES.CLICK)

    if isNewsState then
        self:ChangeCondition(STATES.NEWS, true)
    end
    xRecord.record('4-001')
    local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
    comp:EnterPhoneHomeReq(function()
        KCookie.Set(Constants.IsOpnePageing, 0)
        blocker:RemoveCondition("ExecuteOpenPhone")
    end)

    --[[
    ---要开协程的逻辑
    ---@type Engine.UI.UIRaycastBlocker
    local blocker = CS.Engine.UI.UIRaycastBlocker.Instance
    blocker:AddCondition("ExecuteOpenPhone")
    cs_coroutine.start(function()
        local isNewsState = self.animator:GetBool(STATES.NEWS)
        if isNewsState then
            self:ChangeCondition(STATES.NEWS, false)
        end
        ---播放一个离开动画
        self.animator:SetTrigger(STATES.CLICK)
        self.animator:Play(STATES.CLICK)

        if self.animator then
            local animatorInfo = self.animator:GetCurrentAnimatorStateInfo(0)
            if animatorInfo then
                while not (animatorInfo:IsName(STATES.CLICK) and animatorInfo.normalizedTime >= 0.9) do
                    coroutine.yield(Yielders.EndOfFrame)
                    animatorInfo = self.animator:GetCurrentAnimatorStateInfo(0)
                end
            end

            if isNewsState then
                self:ChangeCondition(STATES.NEWS, true)
            end
        end
        local comp = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.PhoneComponent)
        comp:EnterPhoneHomeReq(function()
            blocker:RemoveCondition("ExecuteOpenPhone")
        end)
    end)
    ]]
end

--主场景显示的时候激活一下红点回调
function IRobotCat:OnUIMainHomeSceneFocusShowEventName(isActive)
    if checkBool(isActive) then
        GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.Phone)
        RobotPet.IsEnable = true
    end
end

function IRobotCat:OnAllMainUI(isActive)
    if not checkBool(isActive) then
        RobotPet.IsEnable = false
    end
end

function IRobotCat:ChangeCondition(stateName, isTrue)
    if isNull(self.animator) then return end
    
    self.animator:SetBool(stateName, isTrue)
end

---Move
---机器人移动方向
---@param param table
function IRobotCat:Move(param)
    if isNull(self.animator) then return end
    if param then
        if param.isFinish then
            ---如果移动完成
            --local a = self.animator
            self.animator:SetBool(STATES.MOVE, false)
            self.animator:SetFloat(STATES.DIRECTION, 0)
            
            --激活一次红点  刷新红点状态
            GameUtils.InvokeRedPointCallBack(Constants.RedPointConst.Phone)
        else
            --关闭红点条件
            self:ChangeCondition(STATES.NEWS, false)

            --local a = self.animator
            self.animator:SetBool(STATES.MOVE, true)
            local direction = -1
            if not checkBool(param.direction) then
                direction = 1
            end
            self.animator:SetFloat(STATES.DIRECTION, direction )
        end
    end
end

---OnUpdate
---执行更新update的事件
function IRobotCat:OnUpdate()
    if self.isUpdating then
        ---执行更新的操作
        if time() - self.startTime >= IDLE_CHANGE_TIME then
            self.startTime = time()
            self.curState = IDLES[math.random(1, 2)]
        end
        if Utils.TouchCount() == 0 then
            if time() - self.noTouchTime >= CHARGE_TIME then
                self.noTouchTime = time()
                self.curState = STATES.CHARGE
            end
        else
            ---重置下点击的时间
            self.noTouchTime = time()
            self.curState = STATES.IDLE
        end

        if self.curState ~= nil then
            ---执行动作
            if self.animator then
                ---@type UnityEngine.Animator
                --local a = self.animator
                self.animator:SetTrigger(self.curState)
                self.lastState = self.curState
            end
            self.curState = nil
        end
    end
end

function IRobotCat:OnDestroy()
    if not IsNull(self._UIMainHomeSceneFocusShowEvent) then
        Events.RemoveListener(Constants.EventNames.UIMainHomeSceneFocusShowEventName, self._UIMainHomeSceneFocusShowEvent)
    end
    if not IsNull(self._AllMainUIEvent) then
        Events.RemoveListener('AllMainUI', self._AllMainUIEvent)
    end
    if not isNull(self._behaviourAction) then
        self._behaviourAction.FixedUpdateAction = nil
    end
    if self.moveHandle then
        Events.RemoveListener(Constants.EventNames.ROBOT_HOME_CATE_MOVE, self.moveHandle)
        self.moveHandle = nil
    end
    if self.__EventHideOrShowWhiteCat then
        Events.RemoveListener("EventHideOrShowWhiteCat", self.__EventHideOrShowWhiteCat)
        self.__EventHideOrShowWhiteCat = nil
    end
    GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.Phone)

    ---@type Engine.Lib.BehaviourAction
    local behaviourAction = self._behaviourAction
    behaviourAction.FixedUpdateAction = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return IRobotCat